import {leagueDrawEntries,drawComparison,powersFor} from './draw.js';
const h=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const difficultyIcons=['🌋','🔥','⚔️','🌤️','🍀'];
export function fixtureComparison(t,revealed=Infinity,{dot=()=>'',color=()=>''}={}){
 const powers=powersFor(t),lookup=new Map(t.teams.map(team=>[team.id,team]));
 return `<div class="draw-comparison" aria-label="Zordan kolaya katılımcı fikstürleri">${drawComparison(t,revealed).map((item,i)=>`<section class="fixture-column team-panel" style="--team-color:${color(item.team)}"><header><span class="difficulty-icon" aria-hidden="true">${difficultyIcons[Math.round(i*(difficultyIcons.length-1)/Math.max(1,t.teams.filter(x=>x.human).length-1))]}</span><h3>${dot(item.team)}${h(item.team.name)}</h3><small>${item.difficulty===null?'Rakipler bekleniyor':`Açılan rakiplerin ortalama gücü: ${item.difficulty.toFixed(2)}`}</small></header><ol>${item.fixtures.map(f=>`<li class="${f.revealed?'draw-revealed':'draw-hidden'}"><small>${f.pot+1}. TORBA · ${f.week}. hafta · ${f.home?'🏠 İç saha':'✈️ Deplasman'}</small><strong>${f.revealed?h(lookup.get(f.opponent).name):'✦ Kura bekleniyor'}</strong>${f.revealed?`<span>GÜÇ ${powers[f.opponent].toFixed(1)}</span>`:''}</li>`).join('')}</ol></section>`).join('')}</div>`;
}
export function drawScreen(t,{dot,color,stageLabel}){
 const draw=t.draw,complete=draw.revealed===draw.total,powers=powersFor(t),lookup=new Map(t.teams.map(team=>[team.id,team]));
 const entries=draw.kind==='league'?leagueDrawEntries(t):[];
 const current=entries[draw.revealed-1];
 const summary=draw.kind==='league'?(current?`${h(lookup.get(current.team).name)} · ${current.pot+1}. torba → ${h(lookup.get(current.opponent).name)}`:'Dört torba. Her torbadan iki rakip.'):`${Math.min(draw.revealed,draw.total)} / ${draw.total} kura topu açıldı`;
 return `<section class="draw-header panel"><div class="panel-body"><span class="eyebrow">${draw.kind==='league'?'LİG AŞAMASI':h(stageLabel)} · KURA GECESİ</span><h1>${complete?'Fikstür belli oldu.':'Sıradaki rakip kim?'}</h1><div class="draw-ball ${complete?'settled':''}" aria-hidden="true">${complete?'✓':'✦'}</div><p role="status" aria-live="polite">${summary}</p><progress value="${draw.revealed}" max="${draw.total}" aria-label="Kura ilerlemesi"></progress><div class="actions">${complete?`<button type="button" class="primary" id="draw-finish">${draw.kind==='league'?'LİG AŞAMASINA GEÇ':'MAÇ MERKEZİNE GEÇ'} →</button>`:'<button type="button" class="secondary" id="draw-next">Sonraki top</button><button type="button" class="text-button" id="draw-all">Tüm kurayı aç</button>'}</div></div></section>${draw.kind==='league'?`<details class="panel draw-pots" open><summary>Güç sırasına göre 4 torba · her torbadan 2 rakip</summary><div class="pots-grid">${t.pots.map((ids,pot)=>`<section><h3>${pot+1}. TORBA</h3>${[...ids].sort((a,b)=>powers[b]-powers[a]).map(id=>`<div class="pot-team ${lookup.get(id).human?'human':''}"><span>${dot(lookup.get(id))}${h(lookup.get(id).name)}</span><b>${powers[id].toFixed(1)}</b></div>`).join('')}</section>`).join('')}</div></details><h2>En zor kuradan en kolaya</h2><p class="muted small">Yalnızca açılan rakipler karşılaştırılır. Tüm rakipler açılınca sekiz maçın ortalama gücüyle son sıra oluşur.</p>${fixtureComparison(t,draw.revealed,{dot,color})}`:`<div class="knockout-draw">${t.bracket.at(-1).ties.map((tie,i)=>`<article class="draw-tie"><span class="eyebrow">${i+1}. EŞLEŞME</span><div class="draw-contender ${draw.revealed>i*2?'draw-revealed':'draw-hidden'}">${draw.revealed>i*2?dot(lookup.get(tie.a))+h(lookup.get(tie.a).name):'✦ İlk top bekleniyor'}</div><small>VS</small><div class="draw-contender ${draw.revealed>i*2+1?'draw-revealed':'draw-hidden'}">${draw.revealed>i*2+1?dot(lookup.get(tie.b))+h(lookup.get(tie.b).name):'✦ Rakip bekleniyor'}</div></article>`).join('')}</div>`}`;
}
